  function cloudServiceCards(vendor){return cloudPalette[vendor].map(function(item,i){var parts=item.split(" · ");return '<button type="button" class="cloud-service-tile" onclick="previewCloudService(\''+vendor+'\','+i+')"><span>'+escText(parts[0])+'</span><small>'+escText(parts[1]||'cloud service')+'</small></button>';}).join("");}
