  function cloudSandboxMarkup(){return '<section class="cloud-sandbox" id="cloudSandbox"><header class="cloud-sandbox-head"><div><span class="eyebrow">DAY 01 · ZERO-COST CLOUD PRACTICE</span><h4>AWS-style and Azure-style cloud lab</h4><p>Build an architecture decision in the portal. This is a learning simulator: it never creates a cloud account, resource, bill or credential.</p></div><span class="cloud-safe-badge">₹0 · $0 · NO ACCOUNT</span></header><div class="cloud-provider-tabs" role="tablist" aria-label="Cloud simulator provider"><button type="button" id="cloudTabAws" class="cloud-provider-tab aws active" onclick="setCloudVendor(\'aws\')" role="tab" aria-selected="true"><b>AWS-style console</b><small>Compute · storage · platform</small></button><button type="button" id="cloudTabAzure" class="cloud-provider-tab azure" onclick="setCloudVendor(\'azure\')" role="tab" aria-selected="false"><b>Azure-style portal</b><small>Apps · data · hybrid</small></button></div><div class="cloud-console" id="cloudConsole"><aside class="cloud-console-rail"><span class="cloud-console-mark">AWS</span><small>SIMULATED<br>LEARNING LAB</small></aside><div class="cloud-console-main"><div class="cloud-console-title"><div><span class="eyebrow" id="cloudConsoleEyebrow">AWS-STYLE SERVICES</span><h5 id="cloudConsoleTitle">Choose a service card</h5></div><span class="cloud-console-region">SIM REGION · INDIA</span></div><div class="cloud-service-grid" id="cloudServiceGrid">'+cloudServiceCards("aws")+'</div><div class="cloud-service-preview" id="cloudServicePreview" aria-live="polite">Select any service tile to understand what engineers use it for. Then build a scenario below.</div></div></div><div class="cloud-learning-map"><div class="cloud-map-copy"><span class="eyebrow">CONCEPT EXPLORER</span><h5>Who manages what?</h5><p>Pick a service or deployment model to reveal the responsibility split and equivalent services.</p></div><div class="cloud-concept-buttons"><div><small>SERVICE MODELS</small><button type="button" onclick="showCloudConcept(\'IaaS\')">IaaS</button><button type="button" onclick="showCloudConcept(\'PaaS\')">PaaS</button><button type="button" onclick="showCloudConcept(\'SaaS\')">SaaS</button></div><div><small>DEPLOYMENT MODELS</small><button type="button" onclick="showCloudConcept(\'Public\')">Public</button><button type="button" onclick="showCloudConcept(\'Private\')">Private</button><button type="button" onclick="showCloudConcept(\'Hybrid\')">Hybrid</button></div></div><article class="cloud-concept-panel" id="cloudConceptPanel"><b>Start with a model</b><p>Select IaaS, PaaS, SaaS, Public, Private or Hybrid to see it in easy language.</p></article></div><section class="cloud-architect"><div class="cloud-architect-head"><div><span class="eyebrow">ARCHITECTURE CHALLENGE</span><h5>Match the workload to its cloud design</h5><p>Choose a business case, service model and deployment model. The simulator checks your reasoning and shows AWS-style and Azure-style equivalents.</p></div><span class="cloud-lab-progress" id="cloudLabProgress">0 / 4 designs explored</span></div><div class="cloud-form-grid"><label>Engineering scenario<select id="cloudScenario" onchange="loadCloudScenario()"><option value="">Choose a scenario…</option>'+cloudScenarioOptions()+'</select></label><label>Service model<select id="cloudServiceModel"><option value="">Choose IaaS, PaaS or SaaS…</option><option>IaaS</option><option>PaaS</option><option>SaaS</option></select></label><label>Deployment model<select id="cloudDeploymentModel"><option value="">Choose Public, Private or Hybrid…</option><option>Public</option><option>Private</option><option>Hybrid</option></select></label><button class="action cloud-run" type="button" onclick="runCloudArchitecture()">Run architecture check</button></div><div class="cloud-architecture-result" id="cloudArchitectureResult" aria-live="polite"><div class="cloud-result-placeholder">Choose a case to start your no-cost cloud design practice.</div></div></section><footer class="cloud-sandbox-footer"><span>Practice safely in this portal. No AWS or Microsoft Azure resources are provisioned.</span><span>Complete a correct architecture match to record your simulator practice.</span></footer></section>';}
