  // Day 1 adds the provider-style cloud sandbox after the shared animated lab.
  // It stays a browser-only simulation and cannot provision any real cloud resource.
  var baseVirtualLabMarkup=virtualLabMarkup;
  virtualLabMarkup=function(day){return baseVirtualLabMarkup(day)+(day===0?cloudSandboxMarkup():"");};

  function studyGuide(day){
    var g=studyGuides[day];
    var topicCards=g.topics.map(function(t,i){return '<article class="study-topic"><span class="study-topic-num">0'+(i+1)+'</span><div><h4>'+escText(t[0])+'</h4><p>'+escText(t[1])+'</p></div></article>';}).join("");
    var useCases=g.industry.map(function(t){return '<li>'+escText(t)+'</li>';}).join("");
    var cs=g.caseStudy,cap=g.capstone;
    var caseMarkup='<section class="industry-case"><div class="study-section-title"><span>04</span><div><h4>Industry case study · '+escText(cs.sector)+'</h4><p>A realistic engineering scenario, with a worked response.</p></div></div><div class="case-grid"><div><b>The challenge</b><p>'+escText(cs.challenge)+'</p></div><div><b>Recommended response</b><p>'+escText(cs.solution)+'</p></div><div><b>Expected outcome</b><p>'+escText(cs.outcome)+'</p></div></div></section>';
    var capSteps=cap.steps.map(function(step,i){return '<li><span>0'+(i+1)+'</span>'+escText(step)+'</li>';}).join("");
    var capMarkup='<section class="solved-capstone"><div class="study-section-title"><span>05</span><div><h4>'+escText(cap.title)+'</h4><p>'+escText(cap.brief)+'</p></div></div><ol>'+capSteps+'</ol><div class="capstone-deliverable"><b>Finished project output</b><p>'+escText(cap.deliverable)+'</p></div></section>';
    var videos=g.videos.map(function(v){return '<article class="study-video"><div class="study-video-title"><span class="eyebrow">WATCH · '+escText(v.by.toUpperCase())+'</span><h4>'+escText(v.title)+'</h4><p>'+escText(v.focus)+'</p></div><div class="video-frame"><iframe loading="lazy" src="https://www.youtube-nocookie.com/embed/'+encodeURIComponent(v.id)+'" title="'+escText(v.title)+'" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><a class="video-fallback" href="https://www.youtube.com/watch?v='+encodeURIComponent(v.id)+'" target="_blank" rel="noopener noreferrer">If the embedded player is unavailable, open this video</a></article>';}).join("");
    return '<section class="panel study-guide"><div class="study-guide-head"><div><span class="eyebrow" style="color:#c6d3ff">DAY 0'+(day+1)+' · COMPLETE STUDY GUIDE</span><h3>'+escText(g.title)+'</h3><p>Read the lesson here, try the animated lab, connect it to real engineering work, then use the embedded videos for another explanation.</p></div><span class="study-book">FIELD GUIDE</span></div><div class="student-analogy"><span class="eyebrow">STUDENT-LIFE ANALOGY</span><p>'+escText(g.analogy)+'</p></div><div class="study-section-title"><span>01</span><div><h4>Easy-language notes</h4><p>Key ideas, explained without assuming prior knowledge.</p></div></div><div class="study-topic-list">'+topicCards+'</div>'+virtualLabMarkup(day)+'<div class="study-industry"><div class="study-section-title"><span>03</span><div><h4>Where engineers use it</h4><p>Examples from real kinds of work and organizations.</p></div></div><ul>'+useCases+'</ul></div>'+caseMarkup+capMarkup+'<div class="study-videos"><div class="study-section-title"><span>06</span><div><h4>Watch important topics</h4><p>Selected YouTube lessons embedded here for in-portal viewing.</p></div></div><div class="study-video-grid">'+videos+'</div></div><div class="study-recap"><b>Study tip from Mentor Kapil</b><span>After each note or video, explain the idea in your own words and name one situation where an engineer would use it.</span></div></section>';
  }

  var requiredSections=["topics","simulator","notes","placement","assignment","pre","post","wheel"];
  function sectionDone(day,key){ensureState();var d=state.dailySections[day]||{};if(key==="pre"||key==="post")return phase(day,key).passed;if(key==="wheel")return wheelState(day).seen.length>=25;return !!d[key];}
  function fullDay(day){return requiredSections.every(function(k){return sectionDone(day,k);});}
  function sectionCount(day){return requiredSections.filter(function(k){return sectionDone(day,k);}).length;}
  function markDailySection(day,key){ensureState();state.dailySections[day]=state.dailySections[day]||{};state.dailySections[day][key]=true;persist();reconcileDay(day);refreshChecklist(day);}
  window.markDailySection=markDailySection;
  function reconcileDay(day){if(!fullDay(day)||state.dayAwards[day])return;var pre=phase(day,"pre"),post=phase(day,"post"),wheel=wheelState(day);var earned=100+100+100+((pre.xpEarned||0)+(post.xpEarned||0))+((wheel.correct||0)*5);state.xp=(state.xp||0)+earned;state.dayAwards[day]=true;if(state.done.indexOf(day)<0)state.done.push(day);if(state.dayBadges.indexOf(day)<0)state.dayBadges.push(day);persist();updateNumbers();if(typeof render==="function")render();toast("Day complete! +"+earned+" XP, badge and certificate unlocked.");}
  function refreshChecklist(day){var el=document.getElementById("dailyChecklist");if(el){var n=sectionCount(day);el.innerHTML=checklistMarkup(day); } if(typeof render==="function")render();}
  function checklistMarkup(day){var labels=["Learning topics","Hands-on simulator","Field notes","Placement tips & FAQs","Daily assignment","Pre-assessment passed","Post-assessment passed","25 wheel questions"];return '<section class="panel daily-checklist" id="dailyChecklist"><div class="panelhead"><div><h3>Day completion checklist</h3><p class="assessment-sub">Finish all 8 sections to claim today’s XP, badge and certificate.</p></div><span class="status">'+sectionCount(day)+' / 8</span></div><div class="checklist-grid">'+requiredSections.map(function(k,i){return '<div class="checklist-item '+(sectionDone(day,k)?'is-done':'')+'"><span>'+(sectionDone(day,k)?'✓':'○')+'</span>'+labels[i]+'</div>';}).join('')+'</div></section>';}

  function wheelState(day) {
    ensureState();
    var s=state.wheel[day];
    if(!s){var pool=shuffle(bank(day).map(function(_,i){return i;})).slice(0,25);s={pool:pool,seen:[],current:null,turns:0,answered:null};state.wheel[day]=s;persist();}
    return s;
  }
  function wheelLabels() {
    var out="";
    for(var i=0;i<25;i++){var angle=i*14.4;out+='<span style="transform:rotate('+angle+'deg) translateY(-92px) rotate(-'+angle+'deg)">'+(i+1)+'</span>';}
    return out;
  }
  function wheelQuestion(day) {
    var s=wheelState(day), q=s.current===null?null:bank(day)[s.current];
    if(!q) return '<div class="wheel-question" id="wheelQuestion"><p class="wheel-empty">Spin to draw one of today’s 25 unique practice questions.</p></div>';
    var choices=q.options.map(function(opt,i){return '<label class="wheel-choice"><input type="radio" name="wheelAnswer" value="'+i+'"><span>'+escText(opt)+'</span></label>';}).join("");
    return '<div class="wheel-question" id="wheelQuestion"><b>'+escText(q.q)+'</b><div class="wheel-options">'+choices+'</div><button class="action" onclick="submitWheel('+day+')">Check answer</button><div class="mentor-note">Mentor Kapil’s hint: '+escText(q.hint)+'</div></div>';
  }
  function wheelPanel(day) {
    var s=wheelState(day), done=s.seen.length, exhausted=done>=25;
    var segments=[];
    for(var n=0;n<25;n++){var color=n%2?"#edf1ff":"#dfe7ff";segments.push(color+" "+(n*14.4)+"deg "+((n+1)*14.4)+"deg");}
    var current=s.current!==null;
    return '<section class="panel wheel-panel"><div class="panelhead"><div><h3>Daily spin challenge</h3><p class="assessment-sub">Spin through 25 distinct questions from today’s topic.</p></div><span class="status">'+done+' / 25</span></div><div class="wheel-layout"><div class="wheel-stage"><div class="wheel-pointer"></div><div class="spin-wheel" id="spinWheel" style="background:conic-gradient('+segments.join(",")+')">'+wheelLabels()+'<div class="wheel-hub">SPIN<br><small>25 Q</small></div></div><button class="action wheel-spin" onclick="spinWheel('+day+')" '+(current||exhausted?'disabled':'')+'>'+(exhausted?"Challenge complete":current?"Answer this question":"Spin the wheel")+'</button></div><div class="wheel-copy"><div class="eyebrow" style="color:#5368c9">ONE QUESTION PER SPIN</div><p>Every question is different. Correct answers add <b>5 XP to your pending day total</b>. Questions you’ve answered won’t return.</p><div id="wheelQuestionHost">'+wheelQuestion(day)+'</div></div></div></section>';
  }

  function securitySuiteMarkup(day) {
    if (day !== 1) return "";
    return "<section class=\"panel security-suite\"><div class=\"security-suite-intro\"><div><span class=\"eyebrow\">DAY 2 · BONUS SECURITY LABS</span><h3>Explore a safe security workstation</h3><p>Two interactive, fictional environments. Commands run against scripted training data only: there is no real shell, server, or network connection.</p></div><span class=\"security-safe-badge\">ISOLATED SIMULATION</span></div><div class=\"security-suite-grid\"><article class=\"security-terminal\"><div class=\"security-terminal-head\"><div><b>Kali-style server simulator</b><small>Mock Linux training host · lab-gateway</small></div><span>● ONLINE</span></div><pre class=\"security-terminal-output\" id=\"securityKaliOutput\" aria-live=\"polite\">Digital Enablement Security Lab\nSimulated Kali-style host · no real commands or packets\nType help to see the safe command list.\n$</pre><form class=\"security-terminal-form\" onsubmit=\"event.preventDefault();runSecurityCommand('kali',1)\"><label for=\"securityKaliInput\">$</label><input id=\"securityKaliInput\" autocomplete=\"off\" spellcheck=\"false\" maxlength=\"100\" aria-label=\"Kali-style simulator command\" placeholder=\"help\"><button class=\"action\" type=\"submit\">Run</button></form><div class=\"security-command-hint\">Try: <code>nmap demo-gateway</code> · <code>attack phishing-demo</code> · <code>server status</code></div></article><article class=\"security-terminal security-terminal-windows\"><div class=\"security-terminal-head\"><div><b>Command Prompt simulator</b><small>Mock Windows training workstation · training.local</small></div><span>● READY</span></div><pre class=\"security-terminal-output\" id=\"securityCmdOutput\" aria-live=\"polite\">Microsoft Windows [Training Shell Simulator]\nAll results are canned examples. No system commands execute.\nType help to see the safe command list.\nC:\\training&gt;</pre><form class=\"security-terminal-form\" onsubmit=\"event.preventDefault();runSecurityCommand('cmd',1)\"><label for=\"securityCmdInput\">C:\\training&gt;</label><input id=\"securityCmdInput\" autocomplete=\"off\" spellcheck=\"false\" maxlength=\"100\" aria-label=\"Command Prompt simulator command\" placeholder=\"help\"><button class=\"action\" type=\"submit\">Run</button></form><div class=\"security-command-hint\">Try: <code>ipconfig</code> · <code>ping training.local</code> · <code>attack sql-demo</code></div></article></div><div class=\"security-mission-box\"><div><span class=\"eyebrow\">DUMMY ATTACKS · DEFENDER MODE</span><h4>Choose a safe incident drill</h4><p>Observe the simulated event, then read the defensive response. These scenarios cannot target a real account or service.</p></div><div class=\"security-mission-buttons\"><button class=\"action secondary\" type=\"button\" onclick=\"runSecurityMission('phishing')\">📨 Phishing alert</button><button class=\"action secondary\" type=\"button\" onclick=\"runSecurityMission('password')\">🔐 Password spray</button><button class=\"action secondary\" type=\"button\" onclick=\"runSecurityMission('sql')\">🧩 SQL input defense</button><button class=\"action secondary\" type=\"button\" onclick=\"runSecurityMission('xss')\">🛡️ Safe output handling</button></div><div class=\"security-mission-result\" id=\"securityMissionResult\" role=\"status\" aria-live=\"polite\">Select a drill to see a fictional alert and the recommended response.</div></div><p class=\"security-safety-note\">Learning boundary: only the simulator’s fixed commands and sample data are supported. Unknown commands are rejected; nothing is sent over the network.</p></section>";
  }

