  window.runSecurityCommand = function(kind, day) {
    if (day !== 1) return;
    if (!portalAllowed(day)) { toast("The learning window is closed. Return during portal hours to use this lab."); return; }
    var input=document.getElementById(kind==="kali"?"securityKaliInput":"securityCmdInput");
    var output=document.getElementById(kind==="kali"?"securityKaliOutput":"securityCmdOutput");
    if(!input||!output)return;
    var command=input.value.trim().replace(/\s+/g," ").slice(0,100);
    if(!command)return;
    var response=(securityLabCommands[kind]||{})[command.toLowerCase()]||"Command blocked: this training console only accepts its listed, fictional commands. Type help.";
    var prompt=kind==="kali"?"$ ":"C:\\training&gt; ";
    output.textContent=(output.textContent+"\n"+prompt+command+"\n"+response).slice(-7000);
    output.scrollTop=output.scrollHeight;
    input.value="";
  };

  window.runSecurityMission = function(name) {
    if(!portalAllowed(1)){toast("The learning window is closed. Return during portal hours to use this lab.");return;}
    var result=document.getElementById("securityMissionResult");
    if(!result)return;
    var drills={
      phishing:"FICTIONAL ALERT: A message threatens to suspend your account and asks you to sign in at an unfamiliar page. Best response: stop, inspect the sender and link without opening it, verify independently, and report it.",
      password:"FICTIONAL ALERT: A sample dashboard shows many failed sign-ins against one training account. No password attempts occurred. Best response: preserve the log, alert the owner, apply rate limits, check MFA, and follow the incident process.",
      sql:"FICTIONAL ALERT: A mock login rejects unexpected input. No database was contacted. Best response: parameterize queries, validate data by type and length, and avoid revealing internal errors.",
      xss:"FICTIONAL ALERT: A training comment contains markup-like text, which this simulator keeps inert. Best response: encode output for its context, sanitize where needed, and set a content security policy."
    };
    result.textContent=drills[name]||"Choose one of the listed training drills.";
  };

