  function beginTimedTest(kind,day){if(!portalAllowed(day)){toast("The learning window is closed. Return during portal hours to start a timed test.");return;}var rec=testRecord(kind,day),limit=kind==="mock"?1:2;if(kind==="final"&&!allDaysComplete()){toast("Complete all five daily learning paths first.");return;}if(rec.passed||(kind==="mock"&&rec.attempts.length>=limit)||rec.attempts.length>=limit){paintTimedResult(kind,day);document.getElementById("timedTestModal").classList.add("show");return;}if(!rec.active){var pool=kind==="mock"?bank(day).map(function(q){return{day:day,id:q.id};}):allQuestionRefs();var count=kind==="mock"?10:25;rec.active=makeTimedAttempt(shuffle(pool).slice(0,count),kind==="mock"?10:30);persist();}if(Date.now()>=rec.active.expiresAt){finishTimedTest(kind,day,true);return;}openTimedTest(kind,day);}
  window.startMockTest=function(day){beginTimedTest("mock",day);};
  window.startFinalAssessment=function(){beginTimedTest("final",4);};
  function paintTimedTest(kind,day){var rec=testRecord(kind,day),a=activeTimedAttempt(kind,day);if(!a){paintTimedResult(kind,day);return;}var total=kind==="mock"?10:25,q=questionForRef(a.refs[a.at]),chosen=a.answers[q.id]||"",opts=q.options.map(function(opt,i){return '<label class="assess-option '+(chosen===opt?'selected':'')+'"><input type="radio" name="timedAnswer" value="'+i+'" '+(chosen===opt?'checked':'')+' onchange="saveTimedAnswer(\''+kind+'\','+day+','+i+')"><span>'+escText(opt)+'</span></label>';}).join("");var title=kind==="mock"?'Day '+(day+1)+' timed mock test':'Five-day final assessment';document.getElementById("timedTestModal").innerHTML='<div class="timed-test-window"><header class="assess-head"><div><div class="eyebrow" style="color:#bdcaff">'+title.toUpperCase()+'</div><h2>Question '+(a.at+1)+' of '+total+'</h2><p>Answers save as you go. The timer continues if you close this panel.</p></div><div class="timed-head-actions"><span class="timed-countdown" id="timedCountdown">--:--</span><button class="assess-close" onclick="closeTimedTest()">Save & close</button></div></header><div class="assess-progress"><i style="width:'+Math.round((a.at+1)/total*100)+'%"></i></div><div class="assess-body"><div class="assess-meta"><span>'+(Object.keys(a.answers).length)+' / '+total+' ANSWERED</span><span>MENTOR KAPIL HINT AVAILABLE AFTER THE TEST</span></div><h3 class="assess-question">'+escText(q.q)+'</h3><div class="assess-options">'+opts+'</div><div class="assess-controls"><button class="action secondary" onclick="moveTimedQuestion(\''+kind+'\','+day+',-1)" '+(a.at===0?'disabled':'')+'>← Previous</button><button class="action secondary" onclick="moveTimedQuestion(\''+kind+'\','+day+',1)" '+(a.at===total-1?'disabled':'')+'>Next →</button><button class="action" onclick="finishTimedTest(\''+kind+'\','+day+',false)">Submit test</button></div></div></div>';}
  window.saveTimedAnswer=function(kind,day,index){var a=activeTimedAttempt(kind,day);if(!a)return;var q=questionForRef(a.refs[a.at]);a.answers[q.id]=q.options[index];persist();paintTimedTest(kind,day);};
  window.moveTimedQuestion=function(kind,day,delta){var a=activeTimedAttempt(kind,day);if(!a)return;var max=kind==="mock"?9:24;a.at=Math.max(0,Math.min(max,a.at+delta));persist();paintTimedTest(kind,day);};
  function startTimedClock(kind,day){if(timedTestInterval)clearInterval(timedTestInterval);timedTestInterval=setInterval(function(){var a=activeTimedAttempt(kind,day);if(!a){clearInterval(timedTestInterval);timedTestInterval=null;return;}var seconds=Math.max(0,Math.ceil((a.expiresAt-Date.now())/1000)),el=document.getElementById("timedCountdown");if(el)el.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+":"+String(seconds%60).padStart(2,'0');if(seconds<=0)window.finishTimedTest(kind,day,true);},1000);}
  window.finishTimedTest=function(kind,day,autoSubmit){var rec=testRecord(kind,day),a=activeTimedAttempt(kind,day);if(!a)return;if(!autoSubmit&&!portalAllowed(day)){toast("The learning window has closed. Your answers are saved; submit during portal hours.");return;}var total=kind==="mock"?10:25;if(!autoSubmit&&Object.keys(a.answers).length<total){toast("Answer all "+total+" questions before submitting.");return;}var correct=a.refs.reduce(function(score,ref){var q=questionForRef(ref);return score+(q&&a.answers[q.id]===q.correct?1:0);},0),attempt={score:correct,passed:correct>=(kind==="mock"?7:18),at:new Date().toISOString(),answered:Object.keys(a.answers).length};rec.attempts.push(attempt);rec.active=null;if(kind==="mock"){if(rec.attempts.length===1){state.xp=(state.xp||0)+20;rec.xpAwarded=true;}}else{rec.passed=rec.passed||attempt.passed;if(rec.passed&&!rec.xpAwarded){state.xp=(state.xp||0)+50;rec.xpAwarded=true;}}persist();updateNumbers();closeTimedTest();paintTimedResult(kind,day);document.getElementById("timedTestModal").classList.add("show");if(typeof render==="function")render();};
  function paintTimedResult(kind,day){var rec=testRecord(kind,day),last=rec.attempts[rec.attempts.length-1],modal=document.getElementById("timedTestModal");if(!last){modal.innerHTML='<div class="timed-test-window"><header class="assess-head"><div><h2>Timed test</h2></div><button class="assess-close" onclick="closeTimedTest()">Close</button></header></div>';return;}var total=kind==="mock"?10:25,passed=kind==="mock"?last.passed:rec.passed,title=kind==="mock"?'Day '+(day+1)+' mock test':'Five-day final assessment',retake=kind==="final"&&!rec.passed&&rec.attempts.length<2;modal.innerHTML='<div class="timed-test-window"><header class="assess-head"><div><div class="eyebrow" style="color:#bdcaff">'+title.toUpperCase()+' · RESULT</div><h2>'+(passed?'Good work — you passed.':'Review and keep learning.')+'</h2></div><button class="assess-close" onclick="closeTimedTest()">Close</button></header><div class="assess-result"><div class="score">'+last.score+'<span style="font-size:20px;color:#8a93a8"> / '+total+'</span></div><p>'+(passed?(kind==="final"?'Final certificate unlocked. +50 XP earned.':'Mock test complete. +20 XP earned.'):'Use the daily notes and Mentor Kapil’s hints to review your answers.' )+'</p><p>'+last.answered+' of '+total+' questions answered'+(retake?' · One retake remains.':'')+'</p>'+(retake?'<button class="action" onclick="startFinalAssessment()">Use one retake</button>':'')+'<button class="action secondary" onclick="closeTimedTest()">Return to lesson</button></div></div>';}

