  function voiceReply(question){var q=question.toLowerCase(),day=voiceDay(),g=studyGuides[day],h=assignmentHelp[day],x=dayExtras[day];if(/assignment/.test(q)&&/solution|answer|fill|model/.test(q))return h.solution;if(/hint|stuck|start/.test(q))return "Assignment hint: "+h.hint;if(/assignment/.test(q))return "Today's assignment: "+lessons[day].assignment+" "+lessons[day].deliverable+" You can ask me for a hint, or use the model answer button beside the submission box.";if(/capstone/.test(q))return g.capstone.title+". "+g.capstone.brief+" A solved project is in today's study guide.";if(/case stud|industry case/.test(q))return "Industry case study: "+g.caseStudy.sector+". "+g.caseStudy.challenge+" Recommended response: "+g.caseStudy.solution;if(/placement|interview|career/.test(q))return "Placement tips: "+x.tips.join(" ");if(/assessment|mock test|exam|quiz/.test(q))return "The daily pre-assessment and post-assessment are available during the 8:00 AM–11:00 PM IST portal window. You also have one 10-minute mock test each day. After all five days, Day 5 unlocks a 25-question, 30-minute final assessment.";if(/progress|xp|badge/.test(q))return "Your current progress is "+(state.done||[]).length+" of 5 days complete, with "+(state.xp||0)+" XP. Today's checklist is "+(typeof sectionCount==="function"?sectionCount(day):0)+" of 8 sections.";if(/case|capstone|project/.test(q))return g.capstone.title+". "+g.capstone.brief+" The solved steps and expected deliverable are in the study guide.";var topic=g.topics.find(function(t){return q.indexOf(t[0].toLowerCase().split(" ")[0])>=0;});if(topic)return topic[0]+": "+topic[1];return "For Day "+(day+1)+", study "+g.title+". I can explain today's topic, assignment, hint, placement tips, industry case study, capstone, assessments, or your XP progress.";}
